-- CF-247 Phase 2 (8 Oct 2026, Platform Admin: "Build 21, add raw capture to 11"): Canadian catalogues published as one page or one JSON
-- file become register adapters (format text_items), all switched off: 16 Ontario college catalogues and the IRCC DLI list. The spec says
-- how the stored file is cut into items, how each field is read and cleaned, which items are skipped, how repeated keys are settled and
-- which fields go into the record (the provider code and name come from the database, as in Layer 1). The reference for each is a
-- verbatim copy of its Layer 1 reader (cf247-register-ca-ref.ts; a contract test checks every copied piece). Side-by-side replay on
-- every stored August copy (coverage-sweep v0.17.26); the driver is started after the worker deploy.
insert into pipeline.register_adapters(source_id, code, label, country_code, spec, notes)
select v.source_id::uuid, v.code, v.label, v.cc, v.spec, 'Phase 2 register adapter (Canada, text_items). Not switched on: the Layer 1 reader stays in charge until the replay passes and a Platform Admin switches it.'
