insert into pipeline.register_replay_runs(source_id, label, storage_path, zip_hash, keep_fields, created_at)
select a.source_id, a.code || ' ' || to_char(e.created_at at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI'), e.storage_path, e.content_hash, false,
       now() + make_interval(secs => x.n * 10 + (row_number() over (partition by x.code order by e.created_at))::int)
  from (values ('ca_algonquin', 'regulatory/CA/ON/algonquin/%', 0), ('ca_boreal', 'regulatory/CA/ON/boreal/%', 1), ('ca_cambrian', 'regulatory/CA/ON/cambrian/%', 2), ('ca_conestoga', 'regulatory/CA/ON/conestoga/%', 3), ('ca_confederation', 'regulatory/CA/ON/confederation/%', 4), ('ca_durham', 'regulatory/CA/ON/durham/%', 5), ('ca_fanshawe_pgwp', 'regulatory/CA/ON/fanshawe-pgwp/%', 6), ('ca_fleming', 'regulatory/CA/ON/fleming/%', 7), ('ca_georgian', 'regulatory/CA/ON/georgian/%', 8), ('ca_lambton', 'regulatory/CA/ON/lambton/%', 9), ('ca_loyalist', 'regulatory/CA/ON/loyalist/%', 10), ('ca_mohawk', 'regulatory/CA/ON/mohawk/%', 11), ('ca_niagara', 'regulatory/CA/ON/niagara/%', 12), ('ca_seneca', 'regulatory/CA/ON/seneca/%.html', 13), ('ca_sheridan', 'regulatory/CA/ON/sheridan/%', 14), ('ca_stclair', 'regulatory/CA/ON/stclair/%', 15), ('ca_ircc_dli', 'regulatory/CA/ircc-dli/2%', 16)) x(code, pattern, n)
  join pipeline.register_adapters a on a.code = x.code
  join pipeline.evidence_artifacts e on e.source_id = a.source_id and e.storage_path like x.pattern;
